colors.value:
oklch(
    calc(var(--surface) + var(--tone-span) * var(--contrast-text)) var(--foreground-chroma)
      var(--surface-hue)
  )

oklch(
    from var(--primary)
      calc(
        l + var(--button-fill-hover-delta) * var(--tone-span) /
          max(var(--tone-span), calc(var(--tone-span) * -1))
      )
      c h
  )

