    from var(--background) calc(l + var(--elevation-step) * var(--elevation-3)) c h
  )

calc(
    var(--tertiary-foreground-level) + (1 - var(--tertiary-foreground-level)) * var(--contrast-up) -
      var(--tertiary-foreground-level) * 0.5 * var(--contrast-down)
  )

oklch(
