oklch(
    from var(--foreground) l calc(c * 0.54) h / calc(2% + 20% * var(--contrast-border))
  )

oklch(
    from var(--foreground) l calc(c * 0.5) h / calc(3% + 38% * var(--contrast-border))
  )

oklch(
